layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgba(89, 197, 236, 0.2); border-left: 8px solid rgb(89, 197, 236); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 12px; padding-bottom: 4px; padding-left: 12px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; line-height: 1.714; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-size: 25.6px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: 3.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: rgb(45, 150, 189); color: rgb(255, 255, 255); color: rgb(45, 150, 189); background-color: transparent; color: rgb(255, 255, 255) }
[data-ryt="nav"] a:hover { color: rgb(45, 150, 189); color: rgb(255, 255, 255) }
[data-ryt="header"]:hover { box-shadow: rgba(0, 0, 0, 0.1) 0px 0px 1.5rem 0px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(45, 150, 189); color: rgb(255, 255, 255); color: rgb(45, 150, 189); background-color: transparent; color: rgb(255, 255, 255) }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: rgb(45, 150, 189); color: rgb(255, 255, 255); color: rgb(239, 57, 130); color: rgb(255, 255, 255) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(45, 150, 189); color: rgb(255, 255, 255); color: rgb(239, 57, 130); color: rgb(189, 235, 252) }
